"""Validate and invoke local and MCP builder tools."""

from __future__ import annotations

import json
from collections.abc import Callable, Mapping, Sequence
from typing import Any, NamedTuple, Optional

import anyio
import structlog

from rasa.agents.schemas.agent_tool_schema import AgentToolSchema
from rasa.mantle.llm.tool_schemas import resolve_builder_tool_schema
from rasa.mantle.memory.manager import (
    MemoryWriteError,
    ProjectMemoryAlreadySetError,
)
from rasa.mantle.orchestration.memory_validation_tools import (
    is_memory_validation_tool,
    snapshot_accessible_memory,
)
from rasa.mantle.orchestration.tool_execution.payload import (
    format_error_as_json,
)
from rasa.mantle.orchestration.tool_execution.validation import (
    unusable_tool_schema_error,
    validate_tool_arguments,
)
from rasa.mantle.orchestration.verbatim_triggers import VerbatimTriggerEvaluator
from rasa.mantle.state.tracker_handle import TrackerHandle
from rasa.mantle.tools.mcp_runtime import MCPRuntime
from rasa.mantle.tools.result import NextInstruction, ToolResult

structlogger = structlog.get_logger()

_NO_INSTRUCTIONS: tuple[NextInstruction, ...] = ()


class PendingInstruction(NamedTuple):
    """A ``ToolResult.next`` instruction waiting to run, with its producing tool."""

    tool_name: str
    instruction: NextInstruction


def _mcp_schema_is_usable(schema: Optional[AgentToolSchema]) -> bool:
    """Return whether an imported MCP tool has a usable argument schema."""
    if schema is None or not schema.parameters:
        return False
    schema_type = schema.parameters.get("type")
    if schema_type is None:
        return True
    if schema_type == "object":
        return True
    return isinstance(schema_type, list) and "object" in schema_type


class ToolInvoker:
    """Validate and invoke builder-defined local and MCP tools.

    Also owns the per-turn queue of ``ToolResult.next`` instructions produced
    by control-flow-capable dispatches (:meth:`call_builder_tool`). The queue
    is drained by the caller once the producing tool's bookkeeping is done.
    """

    def __init__(
        self,
        *,
        mcp_runtime: Optional[MCPRuntime],
        tool_timeout: float,
        verbatim_trigger_evaluator: VerbatimTriggerEvaluator,
    ) -> None:
        self._mcp_runtime = mcp_runtime
        self._tool_timeout = tool_timeout
        self._verbatim_trigger_evaluator = verbatim_trigger_evaluator
        self._pending: list[PendingInstruction] = []

    def begin_user_turn(self) -> None:
        """Drop instructions left over from a cancelled or failed turn."""
        self._pending = []

    def drain_pending_instructions(self) -> list[PendingInstruction]:
        """Return queued ``ToolResult.next`` instructions in order and clear them."""
        pending = self._pending
        self._pending = []
        return pending

    def requeue_instructions(self, items: Sequence[PendingInstruction]) -> None:
        """Put instructions deferred by a confirmation pause back on the queue."""
        self._pending.extend(items)

    def validate_builder_tool_arguments(
        self,
        skill_id: str,
        tool_name: str,
        tool_func: Optional[Callable[..., Any]],
        tool_args: Mapping[str, Any],
    ) -> Optional[str]:
        """Validate arguments against the schema offered for a builder tool."""
        schema = resolve_builder_tool_schema(
            skill_id=skill_id,
            tool_name=tool_name,
            tool_func=tool_func,
            mcp_runtime=self._mcp_runtime,
        )
        if self._is_imported_mcp_tool(
            skill_id, tool_name
        ) and not _mcp_schema_is_usable(schema):
            return unusable_tool_schema_error()
        return validate_tool_arguments(schema, tool_args)

    def _is_imported_mcp_tool(self, skill_id: str, tool_name: str) -> bool:
        return self._mcp_runtime is not None and self._mcp_runtime.has_mcp_tool(
            skill_id, tool_name
        )

    async def call_builder_tool(
        self,
        func: Optional[Callable[..., Any]],
        tool_name: str,
        tool_args: dict[str, Any],
        session: TrackerHandle,
    ) -> str:
        """Invoke a builder tool and queue its outcome response and ``next``.

        ``ToolResult.next`` instructions are appended to the pending queue in
        order; they run only when the caller calls
        :meth:`drain_pending_instructions`.
        """
        frame = session.active_frame
        if frame is not None:
            skill_id, flow_id = session.memory.resolve_scope(frame)
            memory_values_before = snapshot_accessible_memory(
                session.memory, skill_id, flow_id
            )
        else:
            skill_id = flow_id = ""
            memory_values_before = {}

        result, instructions = await self._invoke(func, tool_name, tool_args, session)
        self._queue_instructions(tool_name, instructions)
        self._verbatim_trigger_evaluator.queue_tool_outcome(
            tool_name=tool_name,
            raw_result=result,
            tracker_handle=session,
        )
        if frame is not None:
            self._verbatim_trigger_evaluator.evaluate_when_triggers(
                skill_id,
                flow_id,
                session,
                memory_values_before=memory_values_before,
            )
        return result

    async def call_tool_func(
        self,
        func: Optional[Callable[..., Any]],
        tool_name: str,
        tool_args: dict[str, Any],
        session: TrackerHandle,
        memory_scope: Optional[tuple[str, str]] = None,
    ) -> str:
        """Invoke a local or MCP tool and return its serialized result.

        Used by callers that do not honour control flow (memory validation tools
        such as ``run_after_setting_<field>``, settable writes, button-source
        tools, correction replay), so any ``ToolResult.next`` is logged and
        dropped. The ``on_tool_result`` / ``modify_tool_result`` hook lanes are
        unrelated: they run in the orchestrator around LLM-dispatched calls.
        """
        result, instructions = await self._invoke(
            func, tool_name, tool_args, session, memory_scope
        )
        if instructions:
            structlogger.warning(
                "mantle.skill_executor.tool.next_ignored",
                tool=tool_name,
                count=len(instructions),
                reason=(
                    "control flow is only honoured for LLM-dispatched and "
                    "execute-step tools"
                ),
            )
        return result

    def _queue_instructions(
        self, tool_name: str, instructions: Sequence[NextInstruction]
    ) -> None:
        """Append *instructions* produced by *tool_name* to the pending queue."""
        if not instructions:
            return
        self._pending.extend(
            PendingInstruction(tool_name=tool_name, instruction=instruction)
            for instruction in instructions
        )
        structlogger.debug(
            "mantle.skill_executor.tool.next_queued",
            tool=tool_name,
            count=len(instructions),
        )

    async def _invoke(
        self,
        func: Optional[Callable[..., Any]],
        tool_name: str,
        tool_args: dict[str, Any],
        session: TrackerHandle,
        memory_scope: Optional[tuple[str, str]] = None,
    ) -> tuple[str, Sequence[NextInstruction]]:
        """Invoke a local or MCP tool; return its payload and ``next`` instructions.

        Memory writes retain the producing tool and arguments so correction
        replay can invoke the same producer. MCP failures are sanitized before
        being returned, while local tool errors remain actionable to builders.
        Every error path returns no instructions.
        """
        from rasa.mantle.tools.decorator import ToolContext

        ctx = ToolContext(session, memory_scope)
        if memory_scope is not None:
            skill_id, _ = memory_scope
        else:
            skill_id, _ = session.memory_scope()
        try:
            # Write provenance is needed to replay the producer during corrections.
            with session.recording_write(tool=tool_name, arguments=tool_args):
                raw, error_json = await self._invoke_registered_tool(
                    func, tool_name, tool_args, skill_id, ctx
                )
                if error_json is not None:
                    return error_json, _NO_INSTRUCTIONS
        except MemoryWriteError as exc:
            return self._json_for_memory_write_error(exc, tool_name), _NO_INSTRUCTIONS
        except TimeoutError:
            structlogger.warning(
                "mantle.skill_executor.tool.timeout",
                tool=tool_name,
                timeout_seconds=self._tool_timeout,
            )
            return format_error_as_json(
                f"Tool '{tool_name}' timed out after {self._tool_timeout} seconds."
            ), _NO_INSTRUCTIONS
        except Exception as exc:
            structlogger.error(
                "mantle.skill_executor.tool_error",
                tool=tool_name,
                error_type=type(exc).__name__,
            )
            structlogger.debug(
                "mantle.skill_executor.tool_error.debug",
                tool=tool_name,
                error=str(exc),
            )
            return format_error_as_json(str(exc)), _NO_INSTRUCTIONS

        if not isinstance(raw, ToolResult):
            structlogger.error(
                "mantle.skill_executor.tool.invalid_return",
                tool=tool_name,
                return_type=type(raw).__name__,
            )
            return format_error_as_json(
                f"Tool {tool_name!r} must return a ToolResult, "
                f"got {type(raw).__name__}."
            ), _NO_INSTRUCTIONS

        # Common values such as datetime and Decimal should remain usable by the LLM.
        try:
            return json.dumps(raw.llm_response, default=str), raw.next
        except (TypeError, ValueError) as exc:
            structlogger.error(
                "mantle.skill_executor.tool.unserializable_result",
                tool=tool_name,
                error_type=type(exc).__name__,
            )
            return format_error_as_json(
                f"Tool {tool_name!r} returned a non-serializable result."
            ), _NO_INSTRUCTIONS

    async def _invoke_registered_tool(
        self,
        func: Optional[Callable[..., Any]],
        tool_name: str,
        tool_args: dict[str, Any],
        skill_id: str,
        ctx: Any,
    ) -> tuple[Any, Optional[str]]:
        """Run the MCP or local handler for a tool."""
        if self._mcp_runtime is not None and self._mcp_runtime.has_mcp_tool(
            skill_id, tool_name
        ):
            try:
                return await self._execute_mcp_tool(
                    skill_id, tool_name, tool_args
                ), None
            except Exception as exc:
                # Remote errors may contain hostnames or credentials.
                # Log only the exception type; the LLM gets a sanitized result.
                structlogger.error(
                    "mantle.skill_executor.mcp_tool_error",
                    tool=tool_name,
                    error_type=type(exc).__name__,
                )
                return None, format_error_as_json(
                    f"Tool '{tool_name}' encountered an error."
                )
        if func is not None:
            with anyio.fail_after(self._tool_timeout):
                return await func(context=ctx, **tool_args), None
        return None, format_error_as_json(
            f"Unknown tool '{tool_name}' — no handler registered."
        )

    def _json_for_memory_write_error(
        self, exc: MemoryWriteError, tool_name: str
    ) -> str:
        """Serialize a denied memory write for the LLM, or a no-op for hooks."""
        # Hooks mirror YAML writes: an already-set project field is a no-op,
        # not a rollback.
        if isinstance(exc, ProjectMemoryAlreadySetError) and is_memory_validation_tool(
            tool_name
        ):
            structlogger.warning(
                "mantle.skill_executor.hook.project_already_set",
                tool=tool_name,
                reason=str(exc),
            )
            return json.dumps({"error": None})

        structlogger.warning(
            "mantle.skill_executor.tool.memory_write_denied",
            tool=tool_name,
            reason=str(exc),
        )
        return format_error_as_json(str(exc))

    async def _execute_mcp_tool(
        self,
        skill_id: str,
        tool_name: str,
        arguments: Mapping[str, Any],
    ) -> ToolResult:
        """Execute an MCP tool through the processor-owned runtime."""
        if self._mcp_runtime is None:
            raise RuntimeError(f"MCP runtime is unavailable for tool {tool_name!r}.")
        server_id = self._mcp_runtime.server_id_for(skill_id, tool_name)
        return await self._mcp_runtime.call_mcp_tool(server_id, tool_name, arguments)
